// Une même maison : ambiance, organisation et maquette manipulable.
let projectionTab='ambiance',projectionDay=0;
const projectionDays=[
 {time:'08:00',title:'Ouvrir la maison sur la terrasse.',text:'Imaginer le petit déjeuner au grand air, entre le séjour-cuisine et le jardin. Croissants, jus de fruits, lait et œufs se découvrent dans le marché du Domaine.',image:'maison-l-bois-reference.webp',link:'#producteurs',action:'Composer mon panier',tag:'CHEZ SOI · PRENDRE SON TEMPS'},
 {time:'10:00',title:'Retrouver le lien avec le vivant.',text:'Passer au potager, observer les cultures et découvrir les ateliers. Chacun peut participer selon ses envies : la vie commune laisse aussi de la place à soi.',image:'jardin-photo.webp',link:'#jardin',action:'Découvrir le potager',tag:'AU JARDIN · PARTAGER UN SAVOIR'},
 {time:'15:00',title:'Explorer, puis retrouver son refuge.',text:'Choisir un vélo pour une escapade et retrouver son habitat. Le plan situe les logements, les espaces communs et le parking pour voitures, motos et vélos.',image:'tiny-house-solaire-eau.webp',link:'#velos',action:'Choisir un vélo',tag:'AUTOUR DU DOMAINE · S’ÉCHAPPER'},
 {time:'18:00',title:'Se rencontrer. Décider ensemble.',text:'Imaginer un repas partagé, proposer une activité et prendre part aux décisions. Le Cercle rassemble les échanges ; les conversations internes restent dans l’espace privé des riverains.',image:'jardin-photo.webp',link:'#communaute',action:'Découvrir le Cercle',tag:'LA PLACE COMMUNE · FAIRE ENSEMBLE'}
];
function projectionSwitch(tab){projectionTab=tab;render();document.querySelector(`[data-projection-tab="${tab}"]`)?.focus({preventScroll:true})}
function projectionDaySelect(i){projectionDay=i;const host=$('#projection-day-detail');if(host)host.innerHTML=projectionDayDetail();document.querySelectorAll('[data-projection-day]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.projectionDay)===i))}
function projectionDayDetail(){const d=projectionDays[projectionDay];return `<img src="assets/${d.image}" alt="Illustration de ${d.title.toLowerCase()}" loading="lazy"><div><div class="eyebrow">${d.tag}</div><h3>${d.title}</h3><p>${d.text}</p><a class="textlink" href="${d.link}">${d.action} ↗</a></div>`}
function projectionScene(){if(projectionTab==='ambiance')return `<div class="projection-photo"><img src="assets/maison-l-bois-reference.webp" alt="Visualisation de la maison : deux containers bardés de bois en L, grandes baies et terrasse sous pergola"><span>01 / L’AMBIANCE · VISUEL CONCEPTUEL</span></div>`;if(projectionTab==='plan')return `<div class="projection-plan">${domainPlan()}<div><span class="eyebrow">02 / L’ORGANISATION</span><h3>Le L dessine un espace de vie dehors.</h3><p>Le séjour-cuisine et l’aile nuit s’ouvrent sur la terrasse. Le jardin Yin & Yang prolonge la maison.</p><ul><li>Deux containers assemblés en L</li><li>Une terrasse au cœur de la maison</li><li>Une pergola pour prolonger le séjour</li></ul><small>Schéma d’intention sans cotes d’exécution.</small></div></div>`;return `<div class="projection-model"><div class="domain-viewport ${domainNight?'night':''}" id="domainviewport"><canvas id="domaincanvas" role="img" aria-label="Maquette 3D manipulable de la maison en L avec terrasse, jardin et berger australien. Utiliser les boutons pour tourner ou zoomer."></canvas><div class="domain-caption"><b>03 / EXPLORER LES VOLUMES</b><small>MAQUETTE CONCEPTUELLE</small></div></div><div class="domain-controls"><button aria-label="Tourner à gauche" onclick="domainYaw-=.25;domainRenderer?.draw()">↶</button><button aria-label="Tourner à droite" onclick="domainYaw+=.25;domainRenderer?.draw()">↷</button><button aria-label="Zoom avant" onclick="domainSetZoom(.12)">＋</button><button aria-label="Zoom arrière" onclick="domainSetZoom(-.12)">−</button><button onclick="domainCamera('dessus')">Vue du dessus</button><button onclick="domainCamera('terrasse')">Vue terrasse</button><button aria-pressed="${!domainRoof}" onclick="domainRoof=!domainRoof;projectionSwitch('3d')">${domainRoof?'Voir l’intérieur':'Remettre les toits'}</button><button onclick="domainCamera('reset')">Réinitialiser</button></div><p class="smallnote">Glisser pour tourner, ou utiliser les boutons. Dimensions illustratives.</p></div>`}
views.accueil=function(){travelInit();return `<section class="welcome-hero projection-hero"><img src="assets/maison-l-bois-reference.webp" alt="Maison en L en bois, ouverte sur une terrasse et un jardin tropical"><div class="welcome-shade"></div><div class="welcome-copy"><div class="eyebrow">LE DOMAINE · YIN & YANG</div><h1>Un lieu à habiter.<br>Une vie à partager.</h1><p>Votre terrasse, un jardin vivant, des voisins à rencontrer.<br>Imaginez votre quotidien au Domaine.</p><a class="btn" href="#decouvrir-maison" onclick="event.preventDefault();document.getElementById('decouvrir-maison').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})">Entrer dans le projet ↓</a><a class="welcome-tour" href="#ville">Explorer la petite ville en 3D →</a></div><span class="welcome-label">VISUALISATION DU PROJET · IMAGE ILLUSTRATIVE</span></section><section class="projection-intro" id="decouvrir-maison"><div>${domainEmblem()}<span class="eyebrow">DE L’IMAGE À LA VIE QUOTIDIENNE</span><h2>Plus qu’un lieu.<br>Un Domaine à vivre.</h2></div><p>La maison en photo, son plan en L et sa maquette vous racontent le même projet. Parcourez les trois vues pour comprendre les volumes et imaginer votre place.</p></section><section class="projection-explorer" aria-label="Découvrir la maison en L"><div class="projection-tabs" role="group" aria-label="Choisir une vue de la maison">${[['ambiance','01','L’ambiance'],['plan','02','Le plan en L'],['3d','03','La maison en 3D']].map(([id,n,label])=>`<button data-projection-tab="${id}" aria-pressed="${projectionTab===id}" aria-controls="projection-scene" onclick="projectionSwitch('${id}')"><small>${n}</small>${label}</button>`).join('')}</div><div id="projection-scene">${projectionScene()}</div><div class="projection-bottom"><span>Une maison, deux ailes et une terrasse pour se retrouver.</span><a href="#domaine" class="textlink">La visite complète ↗</a></div></section><section class="projection-life"><div class="sectiontitle"><div><div class="eyebrow">ET SI VOUS Y ÉTIEZ ?</div><h2>Une journée au Domaine.</h2></div><span>À votre rythme.</span></div><div class="projection-hours" role="group" aria-label="Parcourir une journée au Domaine">${projectionDays.map((d,i)=>`<button data-projection-day="${i}" aria-pressed="${projectionDay===i}" aria-controls="projection-day-detail" onclick="projectionDaySelect(${i})"><b>${d.time}</b><span>${['Chez soi','Au potager','À vélo','Ensemble'][i]}</span></button>`).join('')}</div><div class="projection-day" id="projection-day-detail" aria-live="polite">${projectionDayDetail()}</div></section><section class="projection-resources"><img src="assets/tiny-house-solaire-eau.webp" loading="lazy" alt="Tiny house en bois avec panneaux solaires et récupérateur d’eau"><div><div class="eyebrow">LE CONFORT, EN LIEN AVEC LE VIVANT</div><h2>Comprendre ce qui fait vivre votre habitat.</h2><p>Visualisez le soleil sur les toitures, l’eau récupérée et les accès Wi-Fi. L’application présente le suivi envisagé pour chaque logement.</p><div class="projection-resource-links"><a href="#ressources" onclick="event.preventDefault();openEco('C09','solaire')">☀ Solaire & optimisation ↗</a><a href="#ressources" onclick="event.preventDefault();openEco('C09','eau')">◉ Eau & litres récupérés ↗</a><a href="#ressources" onclick="event.preventDefault();openEco('C09','wifi')">⌁ Wi-Fi public & privé ↗</a></div><small>Les mesures et équipements connectés présentés sont simulés.</small></div></section><section class="projection-choice"><a href="#sejours"><span class="eyebrow">POUR QUELQUES NUITS</span><h3>Je viens séjourner.</h3><p>Maison en L, cabane ou tiny house : découvrez les habitats à louer.</p><b>Choisir mon refuge ↗</b></a><a href="/cercle-demo/"><span class="eyebrow">POUR LA VIE AU DOMAINE</span><h3>Je suis riverain.</h3><p>Retrouvez les échanges, les activités et les décisions dans votre espace privé.</p><b>Accéder à mon espace ↗</b></a></section><div class="sectiontitle"><div><div class="eyebrow">VOTRE PARENTHÈSE AU VERT</div><h2>Quel serait votre refuge ?</h2></div><a href="#sejours" class="textlink">Tous les habitats ↗</a></div>${staySearchForm()}<div class="stay-grid">${stayCards(stayCatalog.slice(0,3))}</div><section class="projection-map-note"><div><b>10 containers, une petite ville à explorer.</b><p>3 maisons riveraines privées, 2 suites à louer et 1 maison en L à louer. Retrouvez aussi les jardins, les services et le parking sur le plan.</p></div><a class="btn light" href="#ville">Situer les espaces en 3D ↗</a></section><div class="travel-demo">Présentation conceptuelle : photos illustratives, implantation et journée proposées pour se projeter. Prix, disponibilités, réservations et équipements simulés. Aucun paiement.</div>`};
const renderBeforeProjection=render;render=function(){renderBeforeProjection();if((!location.hash||location.hash==='#accueil')&&projectionTab==='3d')mountDomain()};
render();
